const GOFORGE_QUIZ = [[["Что верно для указателя в Go?",["Всегда размещается в куче","Может указывать на значение, размещённое в стеке","Всегда равен восьми байтам на любой архитектуре","Хранит копию всех полей переменной"],1,"Наличие указателя само по себе не означает heap allocation: решение принимает escape analysis."],["Как получить адрес переменной x?",["*x","&x","unsafe.Sizeof(x)","x[:]"],1,"Оператор & получает адрес адресуемого значения."]],[["Чем различаются массив и срез?",["Массив не имеет len","Срез — дескриптор области backing array","Срез всегда копирует элементы","Массив нельзя передать в функцию"],1,"Slice описывает окно в backing array: указатель, длину и ёмкость."],["Что может произойти при append?",["Всегда меняется исходный массив","Всегда возникает panic","Может выделиться новый backing array","Всегда сохраняется прежний cap"],2,"Если ёмкости не хватает, append может выделить и скопировать данные."]],[["Что возвращает len(string)?",["Число видимых символов","Число рун","Количество байтов","Число UTF-16 единиц"],2,"Строка в Go представляет байты, len сообщает их количество."],["Что возвращает индекс s[i] для строки?",["byte","rune","string","[]byte"],0,"Индексирование строки даёт байт; range декодирует UTF-8."]],[["Что верно о порядке обхода map?",["Всегда сортировка ключей","Не гарантируется","Всегда порядок вставки","Всегда один порядок при каждом запуске"],1,"Спецификация Go не устанавливает порядок итерации map."],["Каков результат чтения отсутствующего ключа map[string]int?",["panic","nil","Нулевое значение int","Ошибка компиляции"],2,"Чтение отсутствующего ключа даёт zero value типа значения."]],[["Когда вычисляются аргументы defer fmt.Println(x)?",["При регистрации defer","Только в конце функции","В новой горутине","После всех return"],0,"Аргументы обычного отложенного вызова вычисляются при выполнении оператора defer."],["В каком порядке выполняются несколько defer?",["FIFO","LIFO","Случайном","Параллельно"],1,"Отложенные вызовы выполняются в обратном порядке их регистрации."]],[["Зачем pointer receiver?",["Только для скорости","Чтобы методы могли изменять исходное значение структуры","Чтобы убрать GC","Чтобы запретить embedding"],1,"Pointer receiver позволяет работать через указатель на исходную структуру."],["Что влияет на padding структуры?",["Имена полей","Размер и требования выравнивания полей","Только число методов","Комментарии"],1,"Выравнивание полей может требовать вставки промежутков между ними."]],[["Когда интерфейс равен nil?",["Когда динамическое значение — typed nil","Когда у него нет методов","Когда динамический тип и значение отсутствуют","Когда переменная содержит *T"],2,"Typed nil с динамическим типом делает значение интерфейса не равным nil."],["Какой тип удовлетворяет интерфейсу с методом, определённым на *T?",["Только T","Только *T","Любой struct","T и *T всегда"],1,"Методы с pointer receiver входят в method set *T, но не T."]],[["Чем воспользоваться для проверки ошибки в цепочке?",["errors.Is","strings.Contains(err.Error())","fmt.Println","recover"],0,"errors.Is учитывает оборачивание ошибок и специальные методы сравнения."],["Когда recover способен перехватить panic?",["Из любой горутины","В обычной функции после panic","В отложенной функции той же горутины","Только из main"],2,"recover эффективен в deferred function во время раскрутки panic той же горутины."]],[["Для чего нужен параметр типа T any?",["Разрешает любой тип для generic-алгоритма","Всегда отключает проверки типов","Использует только interface{} в runtime","Гарантирует отсутствие аллокаций"],0,"any — ограничение, допускающее любой тип, при сохранении статической проверки."],["Что требуется для изменения значения через reflect?",["CanSet и адресуемость","Только Kind==String","Только ValueOf(x)","Всегда достаточно интерфейса"],0,"Для установки значения требуется settable Value, обычно полученный через указатель и Elem."]],[["Что определяет escape analysis?",["Порядок defer","Необходимость размещения значения вне стека","Размер int","Порядок map"],1,"Компилятор оценивает, может ли значение безопасно жить на стеке."],["Можно ли считать sync.Pool долговременным кэшем?",["Да, элементы гарантированно сохраняются","Да, только для строк","Нет, элементы могут исчезнуть в любой момент","Нет, он поддерживает только числа"],2,"sync.Pool вправе удалять элементы, он предназначен для временного переиспользования."]],[["Как tracing GC определяет живые объекты?",["По количеству строк кода","По достижимости от GC roots","По времени создания","Только по размеру"],1,"GC обходит ссылки от корней и помечает достижимые объекты."],["Что означает GOMEMLIMIT?",["Жёсткий предел всей памяти процесса","Мягкую цель памяти, управляемой runtime","Максимальный размер стека","Лимит числа goroutines"],1,"Предел мягкий и относится к памяти, которую учитывает runtime."]],[["Что обозначает P в GMP?",["Только физический процессор","Ресурсы планировщика, нужные для выполнения Go-кода","Номер потока в ОС","Сетевой сокет"],1,"P связывает выполнение Go-кода с ресурсами планировщика."],["Ограничивает ли GOMAXPROCS число всех горутин?",["Да","Нет, он влияет на количество P для параллельного выполнения Go-кода","Да, но только в Linux","Нет, он задаёт лишь размер стека"],1,"Горутин может быть намного больше, чем доступных P."]]];

(function(){
const root=document.querySelector("#tabs");
root.querySelector('[data-tab="deep"]')?.remove();
const css=document.createElement("style");css.textContent='.lesson-wrap{display:grid;gap:17px}.lesson-card{padding:19px;border:1px solid #34475e;background:#162439;border-radius:14px;line-height:1.7}.lesson-card h3{margin:0 0 12px}.lesson-card h4{margin:14px 0 6px;color:#9cdaf6}.lesson-card p{margin:0 0 11px}.lesson-card pre{background:#091321;padding:14px;border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.6 monospace}.lesson-task{border-left:3px solid #39ade6;background:#22354d;padding:10px}.quiz-option{display:block;width:100%;margin:8px 0;white-space:normal}.quiz-result{margin:13px 0;padding:14px;border-radius:10px;background:#22354d}.quiz-card{margin:17px 0}.self-check{padding:14px;border:1px solid #506179;border-radius:10px;margin:12px 0}.self-check label{display:block;margin:7px 0}';
document.head.appendChild(css);
const tabNames={theory:"Изучать",practice:"Писать код",interview:"Проверка знаний",progress:"Прогресс"};
document.querySelectorAll("#tabs [data-tab]").forEach(b=>b.textContent=tabNames[b.dataset.tab]||b.textContent);
const e=x=>String(x).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
s.quizAnswers=s.quizAnswers||{};
s.selfChecks=s.selfChecks||{};
const baseline=render;
render=function(){
 baseline();
 if(s.tab==="theory"){
 const entries=GOFORGE_DEEP[s.unit].topics;
 $("view").innerHTML='<div class="notice"><b>Как учиться:</b> сначала разберись на простом примере, затем прочитай техническую версию. Закрой объяснение, попробуй самостоятельно пересказать и напиши собственный пример. Три раздела — отправная точка, не полный курс.</div><div class="lesson-wrap">'+entries.map((t,i)=>'<section class="lesson-card"><h3>'+(i+1)+'. '+e(t[0])+'</h3><h4>Зачем это знать? Простыми словами</h4><p>'+e(t[1])+'</p><h4>Как устроено технически</h4><p>'+e(t[2])+'</p><h4>Разбери пример</h4><pre>'+e(t[3])+'</pre><h4>Попробуй объяснить</h4><p class="lesson-task">'+e(t[4])+'</p><h4>Напиши самостоятельно</h4><p>'+e(t[5])+'</p></section>').join("")+'</div><div class="actions"><button class="primary" data-tab="interview">Проверить знания</button><button data-tab="practice">Писать код</button></div>';
 }
 if(s.tab==="interview"){
 const qs=GOFORGE_QUIZ[s.unit],answer=s.quizAnswers[s.unit]||{},checks=s.selfChecks[s.unit]||{};
 const attempted=qs.every((q,i)=>answer[i]!==undefined);
 let out='<div class="notice">Этап 1 — тест с однозначно проверяемыми ответами. Этап 2 — объяснение своими словами с самопроверкой. Автоматической AI-оценки свободного текста пока нет.</div>';
 qs.forEach((q,i)=>{out+='<section class="lesson-card quiz-card"><h3>Тест '+(i+1)+' / '+qs.length+'</h3><p>'+e(q[0])+'</p>'+q[1].map((option,j)=>'<button class="quiz-option'+(answer[i]===j?' active':'')+'" data-q="'+i+'" data-a="'+j+'">'+e(String.fromCharCode(65+j))+'. '+e(option)+'</button>').join('')+'</section>'});
 if(attempted){
 const count=qs.filter((q,i)=>answer[i]===q[2]).length;
 out+='<div class="quiz-result"><b>Тест: '+count+' / '+qs.length+'</b><p>'+qs.map((q,i)=>'<span>'+(answer[i]===q[2]?'✓':'✕')+' '+e(q[3])+'</span>').join('<hr>')+'</p></div>';
 }
 out+='<section class="lesson-card"><h3>Этап 2. Объясни своими словами</h3><p>'+e(units[s.unit][6])+'</p><textarea id="answer" placeholder="Сначала напиши ответ самостоятельно. Можно проговорить его вслух.">'+e(s.answers[s.unit]||"")+'</textarea><div class="actions"><button id="rubric">Открыть критерии оценки</button><button class="primary" id="save-answer">Сохранить ответ</button></div><div id="rubric-box" hidden><p><b>Опорное объяснение:</b> '+e(units[s.unit][7])+'</p><p>Проверь себя:</p>'+["Я ответил на вопрос по существу","Я объяснил причинно-следственную связь, а не повторил термин","Я привёл собственный Go-пример или практический случай","Я могу повторить ответ без подсказок"].map((v,i)=>'<label><input type="checkbox" data-check="'+i+'" '+(checks[i]?"checked":"")+'> '+e(v)+'</label>').join('')+'<p class="muted">Это самостоятельная оценка, не результат AI. Отмеченные критерии сохраняются локально.</p></div></section>';
 $("view").innerHTML=out;
 $("view").querySelectorAll("[data-q]").forEach(b=>b.onclick=()=>{s.quizAnswers[s.unit]=s.quizAnswers[s.unit]||{};s.quizAnswers[s.unit][b.dataset.q]=Number(b.dataset.a);store();render()});
 $("answer").oninput=x=>{s.answers[s.unit]=x.target.value;store()};
 $("rubric").onclick=()=>{$("rubric-box").hidden=!$("rubric-box").hidden};
 $("view").querySelectorAll("[data-check]").forEach(c=>c.onchange=()=>{s.selfChecks[s.unit]=s.selfChecks[s.unit]||{};s.selfChecks[s.unit][c.dataset.check]=c.checked;store()});
 $("save-answer").onclick=()=>{if(!$("answer").value.trim())return alert("Сначала напиши ответ");s.recalled.push({unit:s.unit,date:new Date().toISOString(),answer:$("answer").value});store();alert("Ответ сохранён. Качество объяснения ещё не подтверждено автоматически.")};
 }
};
document.addEventListener("click",event=>{if(event.target.closest('[data-tab="theory"]')||event.target.closest('[data-tab="interview"]')){requestAnimationFrame(()=>render())}});
render();
})();
